#define REGIONS 0
#define CYCLING 1

// REGIONS to see buffers side by side
// CYCLING to see buffers cycle over time
#define DEMONSTRATION_MODE REGIONS


// Buffer A indicated by RED LINE:
// Unblurred input 


// Buffer B/C indicated by GREEN LINE:
// Gaussian blur seperated into horizontal and vertical pass
//
// Pros:
//   - O(2n) efficient
//   - accurate result
// Cons:
//   - fixed kernel size with precalculated weights
//
// could be even more optimized by abusing default GPUS bilinear interpolation when texture fetching:
// https://www.rastergrid.com/blog/2010/09/efficient-gaussian-blur-with-linear-sampling/


// Buffer D indicated by BLUE LINE:
// Radial Gaussian blur
//
// Pros:
//   - choosable radius size and quality
//   - no precalculating anything
// Cons:
//   - O(n^2) inefficient
//   - result can look wrong if samples/directions too low or image too noisy


const vec4 RED = vec4(1.0, 0.0, 0.0, 1.0);
const vec4 GREEN = vec4(0.0, 1.0, 0.0, 1.0);
const vec4 BLUE = vec4(0.0, 0.0, 1.0, 1.0);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;

    #if DEMONSTRATION_MODE == REGIONS
    float maskFactor = uv.x;
    #elif DEMONSTRATION_MODE == CYCLING
    float maskFactor = fract(iTime * 0.2);
    #endif

    // Calculate the three buffer masks
    float inputMask = step(maskFactor, 0.33333);
    float gauss2passMask = step(0.33333, maskFactor) * step(maskFactor, 0.66666);
    float gaussRadialMask = step(0.66666, maskFactor);

    // Get the color from each buffer
    vec4 inputTexture = texture(iChannel0, uv);
    vec4 gauss2pass   = texture(iChannel2, uv);
    vec4 gaussRadial  = texture(iChannel3, uv);

    // Combine colors using the masks
    vec4 bufferColor = inputTexture * inputMask + gauss2pass * gauss2passMask + gaussRadial * gaussRadialMask;
    vec4 indicatorColor = RED * inputMask + GREEN * gauss2passMask + BLUE * gaussRadialMask;

    float bufferMask = step(0.01, uv.y);
    float indicatorMask = 1.0 - bufferMask;

    fragColor = bufferColor * bufferMask + indicatorColor * indicatorMask;

}

// Input textures for blurring
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    //most shadertoy example textures are square so we fix aspect ratio
    uv.x *= (iResolution.x / iResolution.y);

    // you could generated some fancy animated fractal here instead of loading a static texture

    if (uv.y < 0.5)
    {
        // the radial blur seems worse on noisy images
        fragColor = texture(iChannel1, uv);
    }
    else
    {
        // seems almost identical on normal images
        fragColor = texture(iChannel0, uv);
    }
}

// Gaussian blur horizontal pass
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;

    // color from input Buffer A
    vec4 originalColor = texture(iChannel0, uv);

    vec4 blurredColor = originalColor * WEIGHTS[0];

    for (int i = 1; i < WEIGHTS_SIZE; i++)
    {
        vec2 xOffset = vec2(float(i) / iResolution.x, 0.0);
        blurredColor += texture(iChannel0, uv + xOffset) * WEIGHTS[i];
        blurredColor += texture(iChannel0, uv - xOffset) * WEIGHTS[i];
    }

    fragColor = blurredColor;
}

// Gaussian blur vertical pass
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;

    // color from horizontal pass
    vec4 originalColor = texture(iChannel0, uv);

    vec4 blurredColor = originalColor * WEIGHTS[0];

    for (int i = 1; i < WEIGHTS_SIZE; i++)
    {
        vec2 yOffset = vec2(0.0, float(i) / iResolution.y);
        blurredColor += texture(iChannel0, uv + yOffset) * WEIGHTS[i];
        blurredColor += texture(iChannel0, uv - yOffset) * WEIGHTS[i];
    }

    fragColor = blurredColor;
}

// Radial Gaussian blur

const float TAU = 6.2831853;
// should be at least 8 directions
const float DIRECTIONS = 16.0; 
const float SAMPLES = 8.0;
// should be about half of WEIGHTS_SIZE for same amount of blur
const float RADIUS = float(WEIGHTS_SIZE) / 2.;


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec2 radiusScaled = RADIUS / iResolution.xy;

    // color from input Buffer A
    vec4 originalColor = texture(iChannel0, uv);

    vec4 blurredColor = originalColor;

    for(float d = 0.0; d < TAU; d+=TAU / DIRECTIONS )
    {
		for(float i=1.0/SAMPLES; i<=1.0; i+=1.0/SAMPLES)
        {
			blurredColor += texture(iChannel0, uv + vec2(cos(d), sin(d)) * radiusScaled * i);		
        }
    }

    blurredColor /= SAMPLES * DIRECTIONS;

    fragColor = blurredColor;
}

// precalculated normalized Gaussian kernel weights for Buffer B and C
//
// single precision floats loose accuracy after roughly 7 decimal points
// normalizing more than 33 floats resulted in outer values being practically 0
// kernel size is therefore 33
//
// the array holds only the right half of the center row of Gaussian kernel matrix
// because its symmetrical in both dimensions
// instead of 1089 (33^2) texture fetches for every pixel we only need 17 ((33+1) / 2)

const int WEIGHTS_SIZE = 17;
const float WEIGHTS[] = float[] (
    0.1320606, 0.1251100, 0.1063435, 0.0810236, 0.0552434, 0.0336264,
    0.0182143, 0.0087429, 0.0036989, 0.0013700, 0.0004403, 0.0001215,
    0.0000283, 0.0000055, 0.0000009, 0.0000001, 0.0000000
);
